-- The catalog: categories, products and their variants (docs/erd.md).
-- IDs are UUIDv7 generated by the API (uuidx.NewV7), so no column has a
-- default id. Money is whole rupiah in bigint. Stock lives on the variants.

CREATE TABLE categories (
    id           uuid        PRIMARY KEY,
    parent_id    uuid,
    level        smallint    NOT NULL CHECK (level IN (1, 2)),
    parent_level smallint    CHECK (parent_level = 1),
    name         text        NOT NULL,
    slug         text        NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT categories_slug_key UNIQUE (slug),
    CONSTRAINT categories_slug_check
        CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 100),
    -- A top-level category has no parent and level 1; a child has both
    -- parent columns and level 2.
    CONSTRAINT categories_parent_check
        CHECK ((parent_id IS NULL) = (level = 1) AND (parent_id IS NULL) = (parent_level IS NULL)),
    -- The target of the composite foreign key below.
    CONSTRAINT categories_id_level_key UNIQUE (id, level),
    -- A child can only point at a level-1 row, so there is no third level and
    -- no category can be its own parent.
    CONSTRAINT categories_parent_fkey FOREIGN KEY (parent_id, parent_level)
        REFERENCES categories (id, level) ON DELETE RESTRICT
);

CREATE TABLE products (
    id          uuid        PRIMARY KEY,
    category_id uuid        NOT NULL,
    name        text        NOT NULL,
    slug        text        NOT NULL,
    description text        NOT NULL DEFAULT '',
    status      text        NOT NULL,
    -- The lowest price among the non-archived variants, kept by the service
    -- in the same transaction as every variant change. Stored so the price
    -- sorts and their cursor can use an index.
    price_from  bigint,
    -- Full-text search over name (weight A) and description (weight B).
    search      tsvector    GENERATED ALWAYS AS (
                    setweight(to_tsvector('indonesian', name), 'A') ||
                    setweight(to_tsvector('indonesian', description), 'B')
                ) STORED,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT products_category_fkey FOREIGN KEY (category_id)
        REFERENCES categories (id) ON DELETE RESTRICT,
    CONSTRAINT products_slug_key UNIQUE (slug),
    CONSTRAINT products_slug_check
        CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) <= 200),
    CONSTRAINT products_status_check CHECK (status IN ('draft', 'active', 'archived')),
    -- An active product always has a price, so it always has a sellable
    -- variant.
    CONSTRAINT products_active_price_check CHECK (status <> 'active' OR price_from IS NOT NULL)
);

-- The planner estimates how many products a search matches from this
-- column's statistics. Product text has many distinct words, so keep a
-- larger sample of them than the default (100).
ALTER TABLE products ALTER COLUMN search SET STATISTICS 1000;

CREATE TABLE product_variants (
    id           uuid        PRIMARY KEY,
    product_id   uuid        NOT NULL,
    sku          text        NOT NULL,
    name         text        NOT NULL,
    price        bigint      NOT NULL,
    stock        integer     NOT NULL,
    -- Optimistic lock: every change to stock also bumps version (Bab 5).
    version      integer     NOT NULL DEFAULT 0,
    weight_grams integer     NOT NULL,
    -- The variant's place in the admin's list, 0 first. It orders variants
    -- with the same price (S, M, L), because UUIDv7 ids made in the same
    -- millisecond are not in creation order.
    position     smallint    NOT NULL,
    -- NULL means sellable. Variants are archived, never deleted, because
    -- order items point to them.
    archived_at  timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT product_variants_product_fkey FOREIGN KEY (product_id)
        REFERENCES products (id) ON DELETE RESTRICT,
    CONSTRAINT product_variants_sku_key UNIQUE (sku),
    CONSTRAINT product_variants_sku_check CHECK (sku = upper(btrim(sku)) AND sku <> ''),
    CONSTRAINT product_variants_price_check CHECK (price > 0),
    -- The last line of defence against overselling.
    CONSTRAINT product_variants_stock_check CHECK (stock >= 0),
    CONSTRAINT product_variants_weight_check CHECK (weight_grams > 0),
    CONSTRAINT product_variants_position_check CHECK (position >= 0)
);

-- Indexes for the catalog queries (docs/erd.md, "Indexes"). Primary keys and
-- unique constraints already have theirs. The product indexes are partial:
-- the storefront only ever lists active products.

-- GET /v1/products?sort=newest
CREATE INDEX products_active_newest_idx
    ON products (created_at DESC, id DESC) WHERE status = 'active';

-- the same, filtered by category
CREATE INDEX products_active_category_newest_idx
    ON products (category_id, created_at DESC, id DESC) WHERE status = 'active';

-- sort=price_asc, and price_desc by scanning it backwards
CREATE INDEX products_active_price_idx
    ON products (price_from, id) WHERE status = 'active';

-- q= full-text search
CREATE INDEX products_search_idx ON products USING gin (search);

-- loading the variants of a page of products
CREATE INDEX product_variants_product_id_idx ON product_variants (product_id);
